INSERT INTO changelog_entries(version,title,summary,content,category,published_at,affected_route,created_at,updated_at) SELECT '2.55.0','Постоянни адреси и пълен каталог на процедурите','Всяка процедура получава собствен постоянен адрес. Картата на сайта проверява пълното покритие и отчита временни грешки, без да публикува непълен списък.','["Запазени са работещите адреси и споделените връзки към панела. Процедури с еднакви съкратени адреси вече водят към отделни страници.","Добавени са видими каталози по държава и странициране, официални източници и точни метаданни.","Езиковите адреси остават достъпни за потребителите; непълните сървърни преводи не се рекламират като индексируеми алтернативи."]','fix','2026-09-17','/procedures',datetime('now'),datetime('now') WHERE NOT EXISTS (SELECT 1 FROM changelog_entries WHERE version='2.55.0');
